export { T as WAXUE_CHAPTERS }

/** 按 chapter slug + test slug 查找音标单元 */
export function getWaxueTest(chapterSlug: string, testSlug: string): WhaleTest | undefined {
  const ch = T.find((c) => c.slug === chapterSlug)
  return ch?.tests.find((t) => t.slug === testSlug)
}
